// Normalize a raw form/webhook payload into one clean lead and flag junk.
// Accepts the Webhook shape ({ body: {...} }) or a flat object (Typeform/Tally/HubSpot after mapping).
const raw = ($json.body && typeof $json.body === 'object') ? $json.body : $json;
const pick = (...keys) => {
  for (const k of keys) {
    const v = raw[k];
    if (v !== undefined && v !== null && String(v).trim() !== '') return String(v).trim();
  }
  return '';
};
let cfg = {};
try { cfg = $('Config').first().json || {}; } catch (e) { cfg = {}; }

const FREE_MAIL = new Set(['gmail.com', 'googlemail.com', 'yahoo.com', 'yahoo.co.uk', 'ymail.com', 'outlook.com', 'hotmail.com',
  'hotmail.co.uk', 'live.com', 'msn.com', 'aol.com', 'icloud.com', 'me.com', 'mac.com', 'proton.me', 'protonmail.com',
  'gmx.com', 'gmx.de', 'web.de', 'mail.com', 'zoho.com', 'yandex.com', 'yandex.ru', 'qq.com', '163.com', 'fastmail.com']);
const DISPOSABLE = new Set(['mailinator.com', 'guerrillamail.com', '10minutemail.com', 'tempmail.com', 'temp-mail.org',
  'yopmail.com', 'trashmail.com', 'sharklasers.com', 'getnada.com', 'dispostable.com', 'maildrop.cc']);
const SPAM_PATTERNS = [/\bseo\b/i, /backlinks?/i, /guest post/i, /rank (your|ur) (web)?site/i, /first page of google/i,
  /\bcrypto\b/i, /\bcasino\b/i, /viagra|cialis/i, /\bloans?\b/i, /web ?design services/i, /lead generation services/i,
  /\bwhatsapp\b.*\+\d/i, /bitcoin/i, /increase (your )?traffic/i];
const COUNTRY_ALIASES = { 'usa': 'US', 'united states': 'US', 'united states of america': 'US', 'america': 'US',
  'uk': 'GB', 'united kingdom': 'GB', 'england': 'GB', 'great britain': 'GB', 'canada': 'CA', 'germany': 'DE',
  'deutschland': 'DE', 'france': 'FR', 'netherlands': 'NL', 'ireland': 'IE', 'australia': 'AU', 'india': 'IN',
  'spain': 'ES', 'italy': 'IT', 'sweden': 'SE', 'brazil': 'BR', 'mexico': 'MX', 'egypt': 'EG' };

const email = pick('email', 'Email', 'email_address', 'work_email').toLowerCase().replace(/^mailto:/, '');
const emailValid = /^[^\s@]+@[^\s@]+\.[a-z]{2,}$/i.test(email);
const domain = emailValid ? email.split('@')[1] : '';
const extraFree = String(cfg.extraFreeMailDomains || '').split(',').map((s) => s.trim().toLowerCase()).filter(Boolean);
const freeMail = FREE_MAIL.has(domain) || extraFree.includes(domain);

let fullName = pick('name', 'full_name', 'fullName', 'Name');
const first = pick('first_name', 'firstName', 'firstname');
const last = pick('last_name', 'lastName', 'lastname');
if (!fullName) fullName = [first, last].filter(Boolean).join(' ');
const parts = fullName.split(/\s+/).filter(Boolean);

let website = pick('website', 'company_website', 'url', 'site', 'Website');
if (website && !/^https?:\/\//i.test(website)) website = 'https://' + website;
if (website) website = website.replace(/\/+$/, '');
if (!website && domain && !freeMail && !DISPOSABLE.has(domain)) website = 'https://' + domain;

const countryRaw = pick('country', 'Country', 'country_code');
const country = COUNTRY_ALIASES[countryRaw.toLowerCase()] || (countryRaw.length === 2 ? countryRaw.toUpperCase() : countryRaw);

const message = pick('message', 'comments', 'Message', 'notes', 'how_can_we_help').slice(0, 2000);
const company = pick('company', 'company_name', 'organization', 'Company');
const jobTitle = pick('job_title', 'jobTitle', 'title', 'role', 'Job Title');

const reasons = [];
if (!email) reasons.push('missing email');
else if (!emailValid) reasons.push('invalid email');
if (DISPOSABLE.has(domain)) reasons.push('disposable email domain');
if (pick('hp', '_hp', 'honeypot', 'fax_number_confirm')) reasons.push('honeypot field filled');
const urlCount = (message.match(/https?:\/\//gi) || []).length;
if (urlCount >= 2) reasons.push(`${urlCount} links in message`);
if (/https?:\/\/|www\./i.test(fullName)) reasons.push('link in name');
const hits = SPAM_PATTERNS.filter((r) => r.test(`${message} ${company}`));
if (hits.length) reasons.push('spam keywords');
if (/^(test|asdf|qwerty|aaa+)@/.test(email) || /^(test|asdf)$/i.test(fullName)) reasons.push('test submission');
if (!fullName && !company && !message) reasons.push('empty form');

return {
  json: {
    lead_id: 'L' + Date.now().toString(36).toUpperCase() + Math.random().toString(36).slice(2, 6).toUpperCase(),
    received_at: new Date().toISOString(),
    full_name: fullName,
    first_name: parts[0] || '',
    last_name: parts.slice(1).join(' '),
    email,
    email_valid: emailValid,
    domain,
    free_mail: freeMail,
    company: company || (!freeMail && domain ? domain.split('.')[0] : ''),
    website,
    job_title: jobTitle,
    country,
    message,
    source: pick('source', 'utm_source', 'form_name') || 'webhook',
    is_junk: reasons.length > 0,
    junk_reasons: reasons.join('; '),
  },
};

// Merge the B2B Email & Domain Scorer answer into the lead. Pro calls /v1/email (deep=true) on RapidAPI with the
// user's key; Free calls the keyless /demo/v1/email (10 calls/day per IP). disposable / invalid -> junk.
// No call (off, or the lead was already junk), an outage, a 429 or a strange answer -> the lead is unchanged and the
// local free-mail / disposable checks from Normalize & Validate Lead stay in charge.
const fromApi = $json.lead_id === undefined;            // the IF's false branch hands us the lead itself
const lead = fromApi ? $('Normalize & Validate Lead').item.json : $json;
const r = fromApi ? $json : {};
const VERDICTS = ['business', 'free', 'role', 'disposable', 'risky', 'invalid', 'unknown'];
const out = { ...lead, email_verdict: '', email_score: '', email_reasons: '', email_typo_fixed_from: '' };
// Pro: fixEmailTypos = true -> a likely typo (user@example.com, the scorer's did_you_mean) is corrected instead of being
// scored as risky, so the reply draft, the CRM contact and the dedupe all use the address the lead meant.
let cfg = {};
try { cfg = $('Config').first().json || {}; } catch (e) { cfg = {}; }
const fixTypos = String(cfg.fixEmailTypos) === 'true';
const FREE = new Set(['gmail.com', 'googlemail.com', 'yahoo.com', 'hotmail.com', 'outlook.com', 'icloud.com', 'aol.com', 'live.com',
  'msn.com', 'comcast.net', 'protonmail.com', 'proton.me', 'me.com', 'mac.com', 'gmx.com', 'yandex.com']);

if (!fromApi) {
  out.email_verdict = lead.is_junk ? 'not_checked (junk)' : 'not_checked';
} else if (r.error) {
  const msg = typeof r.error === 'string' ? r.error : (r.error.message || r.error.description || JSON.stringify(r.error));
  out.email_verdict = /429|demo_daily_limit|too many/i.test(`${msg} ${JSON.stringify(r.error).slice(0, 400)}`)
    ? 'skipped (limit reached)' : 'skipped (scorer unavailable)';
} else if (!VERDICTS.includes(r.verdict)) {
  out.email_verdict = 'skipped (no verdict)';
} else if (fixTypos && typeof r.did_you_mean === 'string' && /^[^\s@]+@[^\s@]+\.[a-z]{2,}$/i.test(r.did_you_mean)
  && ['risky', 'invalid'].includes(r.verdict) && r.did_you_mean.toLowerCase() !== String(lead.email).toLowerCase()) {
  const fixed = r.did_you_mean.toLowerCase();
  const oldDomain = lead.domain, newDomain = fixed.split('@')[1];
  out.email_typo_fixed_from = lead.email;
  out.email = fixed;
  out.domain = newDomain;
  out.free_mail = FREE.has(newDomain) || !!lead.free_mail && newDomain === oldDomain;
  if (lead.website === `https://${oldDomain}`) out.website = out.free_mail ? '' : `https://${newDomain}`;
  if (oldDomain && lead.company === oldDomain.split('.')[0]) out.company = out.free_mail ? '' : newDomain.split('.')[0];
  out.email_verdict = 'typo_fixed';
  out.email_score = '';
  out.email_reasons = [`corrected from ${lead.email}`, ...(Array.isArray(r.reasons) ? r.reasons : [])].join(', ').slice(0, 300);
} else {
  out.email_verdict = r.verdict;
  out.email_score = Number.isFinite(Number(r.score)) ? Math.round(Number(r.score)) : '';
  out.email_reasons = (Array.isArray(r.reasons) ? r.reasons : []).join(', ').slice(0, 300);
  if (r.verdict === 'free') out.free_mail = true;
  if (r.verdict === 'disposable' || r.verdict === 'invalid') {
    out.is_junk = true;
    out.junk_reasons = [lead.junk_reasons, `email scorer: ${r.verdict}${r.did_you_mean ? ` (did you mean ${r.did_you_mean}?)` : ''}`]
      .filter(Boolean).join('; ');
  }
}
return { json: out };

// Dedupe against the Leads sheet: same email = returning lead (row is updated, score/owner kept, no re-scoring);
// same company domain (non free-mail) = known account, so the new contact goes to that account's owner.
// Input is the sheet (read once), so the leads come from 'Is Valid Lead?'.
const rows = $input.all().map((i) => i.json).filter((r) => r && r.email);
const byEmail = new Map(rows.map((r) => [String(r.email).toLowerCase().trim(), r]));
const byDomain = new Map();
for (const r of rows) {
  const d = String(r.domain || String(r.email).split('@')[1] || '').toLowerCase();
  const free = String(r.free_mail).toLowerCase() === 'true';
  if (d && !free && r.owner_email && !byDomain.has(d)) byDomain.set(d, r);
}
const now = new Date().toISOString();
const out = [];
const batch = new Map();
$('Is Valid Lead?').all().forEach((item, idx) => {
  const lead = item.json;
  if (batch.has(lead.email)) { batch.get(lead.email).json.submissions += 1; return; }
  const prev = byEmail.get(lead.email);
  let rec;
  if (prev) {
    rec = {
      ...prev, ...lead,
      lead_id: prev.lead_id || lead.lead_id,
      received_at: prev.received_at || lead.received_at,
      last_seen_at: now,
      submissions: (Number(prev.submissions) || 1) + 1,
      status: 'returning',
      score: prev.score, tier: prev.tier, industry: prev.industry, company_size: prev.company_size,
      owner_name: prev.owner_name || '', owner_email: prev.owner_email || '', owner_slack_id: prev.owner_slack_id || '',
      assignment_reason: prev.assignment_reason || '',
      // never clobber what the rep typed in
      contacted_at: undefined, sla_flagged_at: undefined,
    };
    delete rec.contacted_at; delete rec.sla_flagged_at;
  } else {
    const acct = !lead.free_mail ? byDomain.get(lead.domain) : undefined;
    rec = { ...lead, status: 'new', submissions: 1, last_seen_at: now,
      account_owner_email: acct ? acct.owner_email : '', account_owner_name: acct ? acct.owner_name : '' };
  }
  const o = { json: rec, pairedItem: { item: idx } };
  batch.set(lead.email, o); out.push(o);
});
return out;

// Turn the enrichment response (Apify dataset JSON or raw homepage HTML) into short plain text for the LLM.
const lead = $('Check Duplicates').item.json;
const MAX = 4000;
const decode = (s) => s.replace(/&nbsp;/g, ' ').replace(/&amp;/g, '&').replace(/&lt;/g, '<').replace(/&gt;/g, '>')
  .replace(/&quot;/g, '"').replace(/&#39;|&apos;/g, "'").replace(/&#(\d+);/g, (_, n) => String.fromCharCode(Number(n)));
const squash = (s) => decode(String(s || '')).replace(/\s+/g, ' ').trim();

let title = '', description = '', text = '', status = 'ok', source = 'homepage';
const body = $json.data ?? $json.body ?? '';

if (!lead.website) {
  status = 'skipped';
  source = 'none';
} else if ($json.error || body === '' || body === null) {
  status = 'unreachable';
  source = 'none';
} else {
  const str = typeof body === 'string' ? body : JSON.stringify(body);
  let dataset = null;
  if (Array.isArray(body)) dataset = body;
  else if (/^\s*\[/.test(str)) { try { dataset = JSON.parse(str); } catch (e) { dataset = null; } }
  if (dataset) {
    source = 'apify';
    const page = dataset[0] || {};
    title = squash(page.metadata?.title || page.title);
    description = squash(page.metadata?.description || page.description);
    text = squash(page.text || page.markdown || '');
    if (!text) status = 'unreachable';
  } else {
    const html = str;
    title = squash((html.match(/<title[^>]*>([\s\S]*?)<\/title>/i) || [])[1]);
    description = squash((html.match(/<meta[^>]+name=["']description["'][^>]*content=["']([^"']*)["']/i)
      || html.match(/<meta[^>]+property=["']og:description["'][^>]*content=["']([^"']*)["']/i) || [])[1]);
    text = squash(html
      .replace(/<(script|style|noscript|svg|head|nav|footer)[^>]*>[\s\S]*?<\/\1>/gi, ' ')
      .replace(/<!--[\s\S]*?-->/g, ' ')
      .replace(/<br\s*\/?>|<\/(p|div|li|h[1-6])>/gi, ' ')
      .replace(/<[^>]+>/g, ' '));
    if (!text && !title) status = 'unreachable';
  }
}

return {
  json: {
    ...lead,
    enrichment_source: status === 'ok' ? source : 'none',
    website_status: status,
    website_title: title.slice(0, 200),
    website_description: description.slice(0, 500),
    website_text: text.slice(0, MAX),
  },
};

// Free: the homepage fetch failed (timeout, DNS, 4xx/5xx) or the lead gave no website.
// Never stop the run: keep the lead, mark enrichment as failed/skipped and score on the form data alone.
const lead = $('Check Duplicates').item.json;
const err = $json.error;
const msg = typeof err === 'string' ? err : (err && (err.message || err.description)) || '';
const hasSite = !!lead.website;
return {
  json: {
    ...lead,
    enrichment: hasSite ? 'failed' : 'skipped',
    enrichment_error: hasSite ? String(msg).slice(0, 200) : '',
    website_status: hasSite ? 'unreachable' : 'skipped',
    website_title: '', website_description: '', website_text: '',
  },
};

// Free: one place where both enrichment paths (homepage text, or failed/skipped) meet before scoring.
// Every lead leaves with enrichment = ok | failed | skipped.
const l = $json;
let enrichment = l.enrichment;
if (!enrichment) enrichment = l.website_status === 'ok' ? 'ok' : (l.website ? 'failed' : 'skipped');
return { json: { ...l, enrichment, enrichment_error: l.enrichment_error || '' } };

