// Free: turn Gemini's JSON into the lead's score and tier. Tier comes from Config thresholds, not from the model.
const lead = $('Prepare Lead for Scoring').item.json;
const ai = $json.output || {};
let cfg = {};
try { cfg = $('Config').first().json || {}; } catch (e) { cfg = {}; }
const hot = Number(cfg.hotThreshold ?? 75), warm = Number(cfg.warmThreshold ?? 45);
const clamp = (n) => Math.max(0, Math.min(100, Math.round(Number(n) || 0)));
const score = clamp(ai.score);
const reasons = Array.isArray(ai.reasons) ? ai.reasons.map(String) : (ai.reasons ? [String(ai.reasons)] : []);
return {
  json: {
    ...lead,
    country: String(lead.country || ai.country || '').trim().toUpperCase(),
    industry: String(ai.industry || '').trim(),
    company_size: String(ai.company_size || 'unknown').trim(),
    score,
    tier: score >= hot ? 'hot' : score >= warm ? 'warm' : 'cold',
    scored_by: 'gemini',
    confidence: Math.max(0, Math.min(1, Number(ai.confidence) || 0)),
    reasons: reasons.join(' | '),
    next_action: String(ai.next_action || ''),
    ai_error: '',
  },
};

// Free: fallback when Gemini fails (bad key, quota, outage, unparsable answer). Scores the lead with simple,
// transparent rules on the form data so it is still logged and routed. Marked scored_by = rules.
const lead = $('Prepare Lead for Scoring').item.json;
const err = $json.error;
const errMsg = typeof err === 'string' ? err : (err && (err.message || err.description)) || 'Gemini returned no result';
let cfg = {};
try { cfg = $('Config').first().json || {}; } catch (e) { cfg = {}; }
const hot = Number(cfg.hotThreshold ?? 75), warm = Number(cfg.warmThreshold ?? 45);
const title = String(lead.job_title || '').toLowerCase();
const msg = String(lead.message || '').toLowerCase();
const adj = [];
const SENIORITY = [
  [/\b(ceo|cto|cfo|coo|cmo|cro|chief|founder|co-founder|owner|president|vp|vice president|head of|svp|evp)\b/, 25, 'senior title'],
  [/\bdirector\b/, 18, 'director title'],
  [/\b(manager|lead|principal)\b/, 10, 'manager title'],
  [/\b(student|intern|trainee|assistant|job seeker)\b/, -25, 'junior or student title'],
];
for (const [re, pts, label] of SENIORITY) { if (re.test(title)) { adj.push([label, pts]); break; } }
const INTENT = ['demo', 'pricing', 'price', 'quote', 'trial', 'buy', 'purchase', 'seats', 'licence', 'license', 'roll out',
  'this quarter', 'this month', 'timeline', 'budget', 'contract'];
const intentHits = INTENT.filter((k) => msg.includes(k));
if (intentHits.length) adj.push([`buying intent (${intentHits.slice(0, 3).join(', ')})`, Math.min(25, intentHits.length * 10)]);
const NEGATIVE = ['class project', 'homework', 'internship', 'resume', 'job opening', 'hiring?', 'partnership', 'we offer', 'our services', 'our agency'];
const neg = NEGATIVE.find((k) => msg.includes(k));
if (neg) adj.push([`poor-fit wording ("${neg}")`, -20]);
if (lead.email_verdict === 'role' || lead.email_verdict === 'risky') adj.push([`email check: ${lead.email_verdict}`, -10]);
else if (lead.free_mail || lead.email_verdict === 'free') adj.push(['free-mail address', -15]);
if (lead.enrichment === 'ok') adj.push(['company website readable', 5]);
const score = Math.max(0, Math.min(100, 40 + adj.reduce((s, [, p]) => s + p, 0)));
const tier = score >= hot ? 'hot' : score >= warm ? 'warm' : 'cold';
return {
  json: {
    ...lead,
    industry: '',
    company_size: 'unknown',
    score,
    tier,
    scored_by: 'rules',
    confidence: 0.4,
    reasons: ['Scored by fallback rules (Gemini unavailable)', ...adj.map(([k, p]) => `${p > 0 ? '+' : ''}${p} ${k}`)].join(' | '),
    next_action: tier === 'hot' ? 'Reply today (rule-based score, check the lead yourself)' : tier === 'warm' ? 'Follow up within 2 days' : 'Add to nurture',
    ai_error: String(errMsg).slice(0, 300),
  },
};

// Free: one flat row per new lead, same columns every time, for the Leads tab (and the Nurture tab for cold leads).
const l = $json;
const cols = ['lead_id', 'received_at', 'last_seen_at', 'submissions', 'status', 'full_name', 'first_name', 'email', 'domain',
  'free_mail', 'company', 'website', 'job_title', 'country', 'message', 'source', 'industry', 'company_size', 'score', 'tier',
  'scored_by', 'confidence', 'reasons', 'next_action', 'enrichment', 'website_status', 'email_verdict', 'email_score', 'ai_error'];
const row = {};
for (const c of cols) {
  let v = l[c];
  if (v === undefined || v === null) v = '';
  if (typeof v === 'object') v = JSON.stringify(v);
  row[c] = v;
}
row.last_seen_at = row.last_seen_at || new Date().toISOString();
row.submissions = Number(row.submissions) || 1;
row.status = row.status || 'new';
row.score = row.score === '' ? '' : Number(row.score);
return { json: row };

