// Free: any failed Sheets or Slack step lands here. One row for the Errors tab + one Slack alert, with the lead it was about.
let lead = {};
for (const n of ['Prepare Lead Row', 'Prepare Lead for Scoring', 'Check Duplicates', 'Apply Email Verdict']) {
  try { lead = $(n).item.json; if (lead && lead.email) break; } catch (e) { lead = {}; }
}
if (!lead || !lead.email) lead = $json || {};
const err = $json.error;
const message = typeof err === 'string' ? err : (err?.message || err?.description || JSON.stringify(err ?? $json).slice(0, 500));
let step = 'unknown';
try { step = $prevNode.name || 'unknown'; } catch (e) { step = 'unknown'; }
return {
  json: {
    occurred_at: new Date().toISOString(),
    step,
    error: String(message).slice(0, 1000),
    lead_id: lead.lead_id || '',
    email: lead.email || '',
    company: lead.company || '',
    tier: lead.tier || '',
  },
};
